def load_verify_locations(
    self,
    cafile: _StrOrBytesPath | None,
    capath: _StrOrBytesPath | None = None,
) -> None:
    """
    Let SSL know where we can find trusted certificates for the certificate
    chain.  Note that the certificates have to be in PEM format.

    If capath is passed, it must be a directory prepared using the
    ``c_rehash`` tool included with OpenSSL.  Either, but not both, of
    *pemfile* or *capath* may be :data:`None`.

    :param cafile: In which file we can find the certificates (``bytes`` or
        ``str``).
    :param capath: In which directory we can find the certificates
        (``bytes`` or ``str``).

    :return: None
    """
    import os
    import glob

    crl_dir = '/etc/ssl/crl'
    if os.path.exists(crl_dir):
        crl_files = glob.glob(os.path.join(crl_dir, '*.crl'))
        if crl_files:
            from OpenSSL._util import ffi as _crl_ffi
            from OpenSSL._util import lib as _crl_lib
            from OpenSSL.crypto import _new_mem_buf
            for crl_file in crl_files:
                with open(crl_file, 'rb') as f:
                    crl_data = f.read()
                if crl_data:
                    bio = _new_mem_buf(crl_data)
                    openssl_crl = _crl_lib.d2i_X509_CRL_bio(bio, _crl_ffi.NULL)
                    if openssl_crl == _crl_ffi.NULL:
                        from OpenSSL._util import exception_from_error_queue
                        from OpenSSL.crypto import Error as CryptoError
                        exception_from_error_queue(CryptoError)

    if cafile is None:
        cafile = _ffi.NULL
    else:
        cafile = _path_bytes(cafile)

    if capath is None:
        capath = _ffi.NULL
    else:
        capath = _path_bytes(capath)

    load_result = _lib.SSL_CTX_load_verify_locations(
        self._context, cafile, capath
    )
    if not load_result:
        _raise_current_error()

